def s(title, *paragraphs, rows=None, columns=None, note=None, links=None):
 return dict(title=title, paragraphs=list(paragraphs), rows=rows or [], columns=columns or [], note=note, links=links or [])

def page(slug, title, intro, group, hero, sections, tip, sources, maps, **extra):
 return dict(slug=slug,title=title,intro=intro,group=group,hero=hero,sections=sections,tip=tip,sources=sources,maps=maps,**extra)

PAGES = [
page('micros','Micros: recorridos, horarios y cómo pagar',
 'La micro es una buena aliada para conocer la ciudad con poco presupuesto. Aquí te explico el pago electrónico, dónde mirar tu recorrido y cómo organizar la vuelta.',
 'Dentro de la ciudad','micros',[
 s('Así funciona la red urbana','Busca los buses de Red Punta Arenas de Movilidad y comprueba el número y el letrero de destino. Una misma línea tiene sentidos distintos: la vereda de ida puede no servir para volver. No hace falta memorizar la ciudad; guarda en el teléfono el nombre de tu destino y el paradero que usarás al regresar.',
   'Para subir, espera en un paradero habilitado, identifica el servicio y valida el pasaje. Dentro, conserva espacio de circulación y prepara la bajada con la botonera. Con maletas grandes o una conexión ajustada, compara la comodidad de un traslado directo antes de decidir solo por el precio.'),
 s('Pago electrónico: prepara esto antes de salir','Desde el 2 de enero de 2026 el servicio urbano funciona sin efectivo a bordo. Los medios documentados son la tarjeta del sistema Punta Arenas Conectado, TNE y credencial de persona mayor cuando corresponda, QR de BipayWallet y tarjetas bancarias Visa o Mastercard habilitadas para pago sin contacto.',
   'Acerca únicamente el medio que vas a utilizar y espera la confirmación del validador. Evita presentar la billetera completa con varias tarjetas. Si el pago se rechaza, consulta al conductor y utiliza tu alternativa de respaldo. No se promete que cualquier tarjeta extranjera o billetera móvil funcione con cualquier configuración.',
   rows=[['Tarjeta local','Comprar y cargar saldo antes de viajar.'],['BipayWallet','Descargar la app, registrarse y disponer de saldo; QR para tarifa normal.'],['Tarjeta bancaria','Verificar pago sin contacto y autorización de compras en Chile.'],['TNE / persona mayor','Usar la credencial habilitada para la tarifa correspondiente.']],columns=['Medio','Cómo prepararlo'],links=['bipay-app','bipay-ios','bipay-android','recarga']),
 s('Cuánto cuesta: distinguir tarifa anunciada y cobro efectivo','En febrero de 2026 se comunicó un reajuste a $390 para adulto, $190 para persona mayor y $130 para estudiante. La operadora TransAlerce anunció que mantendría los valores previos. Esa diferencia impide presentar el valor autorizado como una comprobación del cobro efectivo de cada viaje.',
   'Usa la tabla como referencia documentada del reajuste y revisa el importe que muestra el validador o Bipay antes de viajar. La tarifa reducida requiere la credencial habilitada: ser turista estudiante o tener una determinada edad no activa por sí solo un descuento en la aplicación.',
   rows=[['Adulto','$390'],['Persona mayor','$190'],['Estudiante','$130']],columns=['Categoría','Reajuste anunciado para el 28-02-2026'],note='Valores en pesos chilenos. Cobro efectivo actual pendiente de confirmación con el sistema; no se presenta como tarifa garantizada.',links=['bus-tarifa','bus-operador']),
 s('Horarios: una orientación y una consulta para cada día','El plan publicado en enero de 2026 situaba la operación habitual aproximadamente entre 06:30 y 22:00, con ajustes de frecuencia y servicios específicos del Hospital. Es una referencia de planificación, no una tabla vigente para cada línea, domingo o feriado. Las últimas salidas de cabecera tampoco equivalen a la hora de paso por tu paradero.',
   'Antes de salir, selecciona Punta Arenas en Red Regional, abre la línea y comprueba el sentido y las llegadas disponibles. Para un regreso tarde, mira el último servicio antes de hacer la ida. Si no aparecen vehículos o datos, evita interpretar que hay una frecuencia garantizada: conserva una alternativa para volver.',links=['red-ios','red-android','bus-horas']),
 s('Recorridos útiles para empezar','La app oficial Red Regional reúne planificación de viajes, paraderos, posición aproximada de buses y avisos. Para ir de paseo, elige un lugar concreto y revisa la caminata final. Moovit también publica mapas de las líneas 2 y 5; son una ayuda de orientación y conviene contrastarlos con los avisos del operador.',
   rows=[['Zona Franca / Zonaustral','Consultar líneas 2 y 5, sentido y paradero de acceso.'],['Hospital Clínico','Líneas 6 y 6V: información de 2026 mantiene su ingreso al recinto.'],['Línea 8','El cambio de 2026 deja paso exterior al Hospital; no confundir con ingreso.'],['Lomas del Bosque, La Foresta y Valle Los Sauces','Revisar los cambios de 6, 6V y 8 anunciados para julio de 2026.']],columns=['Destino o servicio','Referencia para buscar tu viaje'],links=['mapa-2','mapa-5','bus-cambios']),
 s('Lugares que puedes combinar con la micro','Para una jornada de compras, busca Zonaustral y organiza también el paradero de vuelta. Para el Mall Espacio Urbano Pionero, escribe el nombre completo en el planificador: el mall y Zona Franca son destinos diferentes. Para el Cementerio Sara Braun o el Museo Maggiorino Borgatello, revisa qué parada te deja cerca y cuánto debes caminar.',
   'En el centro puedes bajar y continuar a pie hacia la plaza Muñoz Gamero, el Museo Regional o la Costanera. No atribuyo una parada exacta a cada atracción sin un recorrido actual confirmado. Para el Fuerte Bulnes, Parque del Estrecho, senderos y reservas fuera del radio urbano, organiza un servicio específico: un bus urbano no reemplaza una excursión o un traslado rural.'),
 s('Dónde comprar y recargar: el mapa que sí sirve','El sitio vigente de Bipay tiene un mapa y buscador de comercios por nombre o dirección. Permite revisar el punto de venta y recarga que te quede mejor; consulta su horario antes de caminar hasta allí. No uses como referencia única una captura de un comercio que pudo dejar de atender.',
   'El centro de atención publicado está en Galería Roca, local 18, Presidente Julio A. Roca 886. El correo es puntaarenas@bipay.cl. Bipay publica soporte telefónico +56 4 2256 5827, de lunes a viernes de 09:00 a 18:00. También enlaza la recarga en línea desde $2.000.',links=['bipay','recarga']),
 s('Accesibilidad y visitas con niños','El estándar de los buses incorpora piso bajo y rampa, pero la posibilidad de subir también depende del bus que llegue y del paradero. Si necesitas asistencia, avisa al conductor y considera el acceso desde la vereda. Una característica de la flota no resuelve automáticamente escalones, hielo o un cruce difícil en la caminata final.',
   'Con niños, guarda las cosas antes de subir y procura no bloquear el paso. En días de viento o lluvia, elige un paradero protegido y una actividad cercana a tu bajada. Mi mejor combinación sería un viaje claro de ida, un paseo por un sector y un regreso resuelto, en lugar de varios transbordos improvisados.')],
 'Yo descargaría Red Regional para saber por dónde ir y BipayWallet para pagar. Son dos funciones distintas; tener el mapa no significa tener el pasaje listo.',
 ['red-ios','red-android','bipay','bipay-app','bus-pago','bus-tarifa','bus-operador','bus-horas','bus-cambios'],[('Centro de atención Bipay','Galería Roca Presidente Julio A. Roca 886 Punta Arenas')],inline=[(2,'pago-bipay')]),

page('colectivos','Taxis colectivos: cómo elegir recorrido y pagar',
 'Son autos compartidos que siguen una línea. Pueden resultar muy prácticos si pasan por tu destino: la clave está en comprobar el letrero, el sentido y el valor antes de subir.',
 'Dentro de la ciudad','colectivos',[
 s('Qué es un colectivo en Punta Arenas','En Chile, taxi colectivo suele referirse a un automóvil de recorrido compartido, no a una micro. Otros pasajeros suben y bajan en el camino y el conductor mantiene la ruta de su línea. El pago se calcula por pasajero según el tarifario del servicio; no equivale a contratar el vehículo completo.',
   'Mira el número y los destinos del letrero. Antes de entrar, muestra la dirección y pregunta “¿pasa por aquí y dónde me conviene bajar?”. Una respuesta precisa vale más que suponer que dos autos de apariencia similar van al mismo lugar. Si el punto queda fuera del recorrido, prepara el tramo restante o elige un taxi particular.'),
 s('Tarifas documentadas de Tacopa','La actualización anunciada para las líneas asociadas a Tacopa comenzó el 23 de julio de 2026. El valor publicado es de $900 en horario diurno y $1.000 para noche, trasnoche, domingos y festivos. La información de Seremitt aclara que el alza correspondía a Tacopa, no automáticamente a todas las líneas de la ciudad.',
   rows=[['Diurno','$900'],['Nocturno y trasnoche','$1.000'],['Domingos y festivos','$1.000']],columns=['Bloque publicado por Tacopa','Por pasajero · CLP'],note='Consulta el cartel del vehículo y el bloque horario aplicable. No se verificaron horas de corte comunes a todas las líneas.',links=['colectivo-tarifa','colectivo-alcance']),
 s('Forma de pago y cuánto cuesta al grupo','Prepara efectivo en pesos chilenos y cambio; consulta si ese vehículo dispone de otro medio de pago. No se ha corroborado una red universal de validación Bipay o tarjetas bancarias para todos los colectivos. El pago electrónico de las micros no debe trasladarse como una promesa a este servicio.',
   'Como ejemplo de presupuesto, cuatro pasajeros con tarifa diurna Tacopa de $900 sumarían $3.600, si se aplica esa tarifa a todos y hay espacio para el grupo. El ejemplo es una suma, no una cotización de taxi privado ni garantía de cuatro asientos disponibles. Para menores y equipaje, pregunta las condiciones antes de subir.'),
 s('Recorridos, paraderos y mapas','No encontré un plano público completo y actualizado de todas las líneas de colectivos con horarios garantizados. Por eso no dibujo recorridos supuestos ni publico como vigente un mapa antiguo. La información del cartel de la línea y la señalización de paraderos son las referencias prácticas para confirmar el destino.',
   'Pide al alojamiento una línea concreta para tu dirección de salida y otra referencia para la vuelta. Guarda la esquina o el paradero en el mapa. Una aplicación que ofrece indicaciones hasta la sede de una línea no demuestra que esté siguiendo sus vehículos en vivo; evita confundir una ubicación comercial con el trazado del colectivo.'),
 s('Qué visitas encajan mejor','El colectivo puede ser útil para conectar tu hospedaje con el centro, comercio o un servicio urbano cuando el recorrido coincide. Para ir al Cementerio, al mall o a Zona Franca, confirma el acceso que realmente usa la línea; dejarte en una avenida cercana y dejarte junto a la puerta son cosas distintas.',
   'Si quieres visitar Nao Victoria, una reserva o un destino fuera del área habitual de la línea, no supongas que el conductor se desviará. Para un grupo con varias paradas, un traslado acordado puede ofrecer un plan más claro. En cualquier caso, resuelve el punto de regreso antes de empezar la visita.'),
 s('Horarios, noche y disponibilidad','No hay aquí un horario único de apertura y cierre para todos los colectivos. La circulación varía por línea, demanda y jornada, y la existencia de una tarifa nocturna no garantiza que encuentres un auto a cualquier hora. Para una cena que termine tarde, conserva el contacto de un taxi o una aplicación como alternativa.',
   'Si debes llegar a una barcaza, un bus interurbano o un vuelo, calcula también la espera y la caminata al destino. El colectivo funciona bien cuando coincide con la ruta y tienes margen; no conviene basar una conexión ajustada en una frecuencia que no pudiste confirmar.'),
 s('Maletas, movilidad y forma de viajar','El espacio es compartido: consulta antes de cargar maletas grandes o un coche de niño. Si necesitas un vehículo accesible o un sistema de retención infantil, coordina una opción que lo confirme expresamente. Que un auto tenga lugar para pasajeros no acredita que pueda atender esas necesidades.',
   'Durante el trayecto, utiliza el cinturón y avisa la bajada con anticipación en un lugar permitido. Al bajar, comprueba tus pertenencias y espera a tener visibilidad antes de cruzar. Para una primera visita, aprender una sola ruta útil y su regreso puede ser suficiente para moverte con confianza.')],
 'Yo preguntaría el destino y el precio en la misma frase antes de subir. Y guardaría el paradero de regreso, no solamente el lugar donde bajé.',
 ['colectivo-tarifa','colectivo-alcance'],[('Centro: referencia para orientarte, no terminal de colectivos','Plaza Muñoz Gamero Punta Arenas')]),

page('uber','Uber, DiDi e inDrive: viajar con aplicaciones',
 'Cómo comparar un viaje, elegir el punto de recogida y revisar precio y pago. Las aplicaciones ayudan en la ciudad, pero una pantalla disponible no garantiza un auto para cualquier camino rural.',
 'Dentro de la ciudad','noche',[
 s('Qué aplicaciones están documentadas','Uber publica cobertura para Punta Arenas y DiDi incluye la ciudad entre sus operaciones en Chile. Para inDrive existe actividad documentada en el registro público local de 2026; comprueba dentro de su aplicación qué servicios y conductores están disponibles en tu ubicación. Ninguna de estas referencias equivale a una flota disponible en todo momento.',
   rows=[['Uber','Precio y opciones mostrados antes de solicitar; disponibilidad en la app.'],['DiDi','Ciudad incluida por la plataforma; revisar categorías y medios de pago locales.'],['inDrive','Modelo de precio acordado; revisar ofertas, conductor y condiciones antes de aceptar.'],['Cabify y otras','Cobertura local actual no corroborada en esta revisión; no se presentan como respaldo confirmado.']],columns=['Aplicación','Cómo usar la información'],links=['uber','didi','indrive']),
 s('Antes de llegar: teléfono, cuenta y conexión','Instala la aplicación desde su tienda oficial y comprueba que puedes acceder a tu cuenta antes de necesitar un viaje. Mantén operativo el número que recibe verificaciones y revisa tu conexión de datos. Si cambias de SIM durante el viaje, asegúrate de conservar el acceso a la cuenta y los canales de contacto.',
   'Guarda la dirección del alojamiento y un punto de referencia visible. En el aeropuerto, termina primero el retiro de equipaje; en un restaurante, evita fijar la recogida desde una ubicación GPS imprecisa dentro del edificio. El punto que ves en la pantalla y la entrada por la que saldrás deben coincidir.'),
 s('Pedir el viaje, paso a paso','Introduce origen y destino completos. Comprueba la ubicación del pin, el lado de la calle, los pasajeros y las maletas. Revisa el precio, el medio de pago y las condiciones visibles. Solicita cuando estés listo para salir; la espera puede generar cargos de acuerdo con la plataforma.',
   'Cuando se asigne el vehículo, compara matrícula, modelo y nombre del conductor. Utiliza el chat o la llamada de la app para aclarar dónde encontrarse. Si el vehículo no coincide con lo indicado, no subas y resuélvelo en la plataforma. El viaje debe quedar registrado en la solicitud que aceptaste.'),
 s('Precio: por qué no publico una tarifa fija','El importe depende de origen, destino, demanda y condiciones del servicio. Uber indica que las recogidas pueden demorar más que en ciudades grandes y ofrece consulta de precio dentro de la aplicación. La cotización es la que debes revisar para tu viaje, no una cifra universal para todo Punta Arenas.',
   'Compara el mismo recorrido y número de pasajeros entre las opciones que realmente aparezcan. Ten en cuenta cambios de destino, paradas, espera y cancelación según las condiciones mostradas. Si una plataforma ofrece programación anticipada, revisa su política específica y el estado de la asignación; no interpretes un recordatorio como confirmación automática de conductor.'),
 s('Tarjetas, efectivo y moneda','Revisa el medio de pago seleccionado antes de solicitar. Las opciones dependen de la aplicación, la cuenta y el servicio: utiliza las que aparezcan habilitadas para tu viaje. Si pagas con una tarjeta emitida fuera de Chile, comprueba con tu banco que admite la operación y que no requiere una autorización adicional.',
   'Si la app permite efectivo, confirma el importe en pesos chilenos y lleva cambio. Si figura tarjeta, revisa el cobro y el recibo desde la propia plataforma; evita resolver una diferencia mediante un segundo pago sin comprobar qué pasó con el primero. Conserva el comprobante para cualquier consulta posterior.'),
 s('Cómo cambia la experiencia con inDrive','El modelo de inDrive permite que pasajero y conductor acuerden el precio antes del viaje. Revisa las propuestas y el perfil, no solo la oferta más baja. Confirma el destino, el punto de recogida y el método de pago antes de aceptar. Una negociación no sustituye la verificación del auto y del conductor.',
   'Mantén la coordinación y el registro dentro de la aplicación. Si el grupo necesita maletero, una parada o un requisito de acceso, indícalo antes de elegir. No se publican aquí categorías, tarifas mínimas ni métodos de pago de otros países como si fueran los mismos para Punta Arenas.'),
 s('Aeropuerto, puerto y salidas de madrugada','En terminales, sigue el punto de recogida autorizado y las instrucciones de la app. En PUQ puedes comparar con el taxi oficial, cuyas tarifas publica el aeropuerto. En Tres Puentes indica el terminal y evita quedar esperando en un sector que interfiera con el embarque.',
   'Para un vuelo temprano, calcula el trayecto, la posible espera y la anticipación que exige tu aerolínea. Si no hay vehículos o se cancela una solicitud, utiliza una alternativa que puedas confirmar. Tener más de una aplicación instalada ayuda a comparar, pero pedir varios viajes simultáneos puede terminar generando cancelaciones y cargos.'),
 s('Regreso desde reservas y caminos rurales','Una app que funciona en el centro no acredita cobertura en Laguna Parrillar, San Isidro, Fuerte Bulnes o una reserva. Antes de ir, confirma cómo volverás, si habrá señal y si el transporte acepta el camino. Para esos paseos suele ser más claro contratar ida y regreso o un programa completo.',
   'Comparte el recorrido con una persona de confianza y utiliza las herramientas de ayuda de la plataforma cuando corresponda. Para un objeto olvidado o una diferencia de cobro, abre el viaje en el historial y entra al soporte de esa solicitud. Es la manera de relacionar la consulta con el servicio concreto.')],
 'Yo elegiría la aplicación por el auto realmente disponible, el precio final y un punto de recogida claro. Para salir de la ciudad, dejaría el regreso confirmado antes de pedir la ida.',
 ['uber','didi','didi-pasajero','indrive','indrive-local','puq'],[('Centro urbano de referencia','Plaza Muñoz Gamero Punta Arenas')]),

page('taxis','Taxis: ciudad, aeropuerto y traslados acordados',
 'Un servicio directo ayuda con maletas, horarios especiales o un grupo. Antes de salir, acuerda el destino, cómo se cobrará y qué incluye el traslado.',
 'Dentro de la ciudad','taxi-candidato',[
 s('Taxi particular y colectivo son servicios diferentes','Cuando contratas un taxi particular, necesitas un traslado directo para tu grupo y una dirección concreta. Un colectivo comparte recorrido con otros pasajeros. Distinguirlos evita confundir una tarifa individual de línea con el precio de un servicio completo.',
   'Al coordinar, indica pasajeros, equipaje, dirección y hora. Pregunta cómo se calcula el cobro, si hay un total acordado y qué puede modificarlo. Para una conexión importante, conserva el nombre del servicio y una confirmación por escrito.'),
 s('Taxi oficial del aeropuerto: precios publicados','Aeropuertos Australes publica valores para el taxi oficial de PUQ. Son tarifas del traslado indicado, diferentes del pasaje por persona de una micro o colectivo. Confirma con el servicio qué zona corresponde exactamente a tu hospedaje y el valor antes de subir.',
   rows=[['Aeropuerto ↔ ciudad de Punta Arenas','$13.000'],['Río de los Ciervos, Archipiélago Chiloé y 18 de Septiembre','$16.000'],['Leñadura y sectores aledaños al sur','$18.000']],columns=['Tramo / sector publicado','CLP · taxi oficial'],note='Consulta del sitio del aeropuerto: 22-10-2026. Revisar capacidad, equipaje, zona y vigencia al contratar.',links=['puq']),
 s('Cómo contratar y pagar','Utiliza el servicio identificado del terminal o una empresa que puedas reconocer y contactar. Confirma si el precio se cobra por vehículo y qué medio acepta: efectivo, tarjeta u otra opción deben acordarse con el operador, sin asumir que todos funcionan igual.',
   'Para un traslado privado reservado, solicita el importe final, punto de encuentro y política si el vuelo se retrasa. Para salidas urbanas, entrega la dirección completa en lugar de una referencia ambigua. Si viajas con una silla infantil, silla de ruedas o equipaje de gran tamaño, consulta por un vehículo adecuado antes de confirmar.'),
 s('Visitas a las afueras: espera e ida y regreso','Para ir a Nao Victoria, al Parque del Estrecho o al inicio de un sendero, pregunta si el precio cubre solo el traslado de ida, la espera o también el regreso. Define las paradas, cuánto tiempo estarán y cómo se comunicarán si cambia el plan.',
   'No se presenta cualquier taxi como guía turístico ni como vehículo autorizado para todos los caminos. Las entradas, comida y navegación deben aparecer expresamente incluidas si contratas un programa. Comparar dos cotizaciones requiere que tengan el mismo alcance.'),
 s('Horarios especiales y conexiones','El aeropuerto informa una oferta de transporte, pero no se promete aquí un vehículo específico a cualquier hora sin reserva. Para madrugada, invierno o un grupo numeroso, coordina con anticipación y vuelve a confirmar antes de acostarte.',
   'Si debes abordar un ferry, un bus o un avión, suma la presentación requerida por el operador y el traslado hasta el acceso correcto. Una hora de salida no es una hora recomendable para recién llegar al terminal. Conserva una alternativa por si el servicio reservado no puede realizarse.'),
 s('Una salida urbana que puede tener sentido','Para varias personas con poco tiempo, puedes acordar un recorrido con paradas en el Cementerio, un mirador y el sector norte. Decide si quieren solo bajar a fotografiar o realizar una visita completa: esa diferencia cambia el tiempo de espera y el presupuesto.',
   'Para el centro, muchas visitas se combinan caminando y quizá solo necesites taxi para el tramo de ida o vuelta al hospedaje. Pagar un traslado directo donde aporta comodidad permite dejar el resto del paseo a tu ritmo.')],
 'Yo pediría que la cotización diga claramente “ida”, “ida y vuelta” o “con espera”. Es el detalle que más ayuda a comparar servicios sin sorpresas.',
 ['puq','puq-vuelos'],[('Aeropuerto Presidente Carlos Ibáñez del Campo','Aeropuerto Presidente Carlos Ibáñez del Campo Punta Arenas')]),

page('barcazas','Barcazas: elegir el cruce correcto',
 'Dos conexiones distintas cruzan hacia Tierra del Fuego. Compara terminales, navegación, precio y carretera antes de decidir: llegar a la isla no significa llegar a tu visita.',
 'Estrecho y Tierra del Fuego','barcaza',[
 s('Porvenir y Primera Angostura, sin confundirlos','La ruta Punta Arenas–Porvenir conecta Tres Puentes con Bahía Chilota y el operador informa unas dos horas de navegación. Primera Angostura une Punta Delgada con Bahía Azul; exige primero recorrer por tierra desde Punta Arenas hasta el cruce.',
   rows=[['Punta Arenas–Porvenir','Tres Puentes ↔ Bahía Chilota','Navegación aproximada de 2 horas; calendario de zarpes.'],['Primera Angostura','Punta Delgada ↔ Bahía Azul','Cruce corto; sumar carretera, espera y continuación en la isla.']],columns=['Ruta','Terminales','Cómo pensar el viaje']),
 s('Elegir según el destino y el vehículo','Para conocer Porvenir a pie, estudia también cómo viajar desde Bahía Chilota hasta la ciudad. Para un circuito en auto por Tierra del Fuego, compara las horas de carretera de ambos lados y el horario de cada cruce. El ferry más barato no necesariamente produce la jornada más corta.',
   'Si vas a la Reserva Natural Pingüino Rey, coordina primero el cupo y arma los desplazamientos alrededor de esa visita. El cruce, la carretera y la entrada son servicios distintos. Una excursión que los resuelve puede ser conveniente, pero revisa qué incluye realmente el programa.'),
 s('Precios: pasajero, conductor y acompañantes','Los tarifarios de TABSA distinguen entre pasajeros y categorías de rodados. En Porvenir, el vehículo incluye conductor y los acompañantes se pagan aparte. Primera Angostura publica pasajeros gratis y cobro por vehículo. La clasificación cambia para motorhome, van, carro y dimensiones especiales.',
   'En las fichas individuales encontrarás los importes consultados y el enlace al documento del operador. Revisa el costo de ida y de vuelta, no solo el primer cruce. Una reserva de visitante o un auto arrendado no incorpora automáticamente un descuento de residente.'),
 s('Compra, documentación y niños','TABSA permite comprar en su sitio y en oficinas. El pasaje corresponde a la ruta adquirida y no se intercambia automáticamente por otra conexión. Al reservar, identifica pasajeros y vehículo según la compra; los menores también necesitan tarjeta de embarque, incluso cuando su categoría no paga.',
   'Con un auto arrendado, pregunta cómo incorporar o corregir la matrícula antes de embarcar. Guarda pasajes y documentos en el teléfono y una copia accesible sin datos. Para horarios de presentación, acepta el indicado en el billete y las condiciones del servicio concreto, no una regla única inventada para todas las naves.'),
 s('Mal tiempo, cambios y equipaje','Revisa el estado del cruce antes de conducir hasta el terminal y nuevamente durante la jornada. Según las preguntas frecuentes de TABSA, una suspensión meteorológica traslada los pasajes al siguiente cruce cercano y permite gestionar alternativas con reservas si no te acomoda. Confirma las condiciones de tu compra.',
   'El operador informa que no hay guarda equipaje en los terminales portuarios. Viaja con lo que puedas transportar y deja resuelta la custodia en otro lugar si la necesitas. Consulta el transporte de mascotas antes de reservar: el acceso a la sala de pasajeros tiene condiciones específicas.',links=['tabsa-estado','tabsa-faq']),
 s('Organizar el día completo','El horario publicado es un zarpe: al cálculo debes sumar llegada anticipada, filas, carga o descarga y traslado desde el desembarque. No programes una visita al otro lado usando únicamente la duración del agua. Para una conexión aérea posterior, una noche de margen puede darte más flexibilidad que un enlace ajustado.',
   'Yo prepararía dos planes: la jornada que quiero hacer y lo que cambia si el cruce se atrasa. Si el viaje depende de una reserva con horario, consulta también su política ante cambios de transporte. Esa coordinación permite decidir mejor si ir por cuenta propia o con un operador.')],
 'Yo elegiría primero el recorrido completo y después el ferry. Un buen cruce es el que encaja con tu destino, tu vuelta y la flexibilidad de tu viaje.',
 ['porvenir','porvenir-precios','angostura','angostura-precios','tabsa-faq','tabsa-estado'],[('Tres Puentes · Punta Arenas','Embarcadero Tres Puentes Juan Williams 06450 Punta Arenas')]),

page('punta-arenas-porvenir','Ferry Punta Arenas–Porvenir: horarios y tarifas',
 'El Pathagon conecta Tres Puentes y Bahía Chilota. Es una forma de cruzar a Tierra del Fuego con vehículo o a pie, preparando por separado el acceso a Porvenir y el regreso.',
 'Estrecho y Tierra del Fuego','porvenir-pathagon',[
 s('De dónde sale y dónde llegas','El embarque en Punta Arenas se realiza en Tres Puentes, con referencia comercial de TABSA en Juan Williams 06450. En Tierra del Fuego se desembarca en Bahía Chilota. El operador publica unas dos horas de navegación; no es el tiempo total desde tu hospedaje hasta el centro de Porvenir.',
   'Si viajas a pie, coordina el tramo entre el terminal y la ciudad para ambos sentidos. Si viajas en auto, revisa el horario al que debes presentarte con el vehículo y el acceso de embarque. Guarda las dos ubicaciones: buscar solo “Porvenir” no identifica necesariamente el terminal.'),
 s('Horarios: calendario consultado, no salida fija diaria','TABSA publica un calendario por fecha y sentido. Estos son ejemplos de la semana consultada el 22 de octubre de 2026; no se trasladan automáticamente a otra semana. El enlace del operador es la referencia para elegir el día de tu viaje.',
   rows=[['22-10-2026','09:00 y 18:00','15:00'],['23-10-2026','17:30','08:00 y 20:30'],['24-10-2026','09:30','19:00'],['25-10-2026','09:30','19:00'],['26-10-2026','09:00','19:00'],['27-10-2026','09:00 y 18:00','15:00'],['28-10-2026','17:30','08:00 y 20:30']],columns=['Fecha','Punta Arenas → Porvenir','Porvenir → Punta Arenas'],note='Muestra histórica de consulta. Confirmar siempre fecha, estado del cruce y presentación al embarque.',links=['porvenir-horas','tabsa-estado']),
 s('Tarifas de pasajeros y vehículos','El documento publicado por TABSA indica vigencia desde el 9 de abril de 2026. La categoría de automóvil o camioneta considera un largo máximo de seis metros. Las tarifas de rodados incluyen conductor, pero no acompañantes. Confirma la categoría cuando se trate de van, motorhome o carro de arrastre.',
   rows=[['Pasajero','$12.000'],['Pasajero adulto mayor','$10.000'],['Menor de 6 años','Sin pago; requiere tarjeta de embarque'],['Automóvil o camioneta hasta 6 m, con conductor','$78.500'],['Moto o cuatrimoto','$39.500'],['Motorhome / van / furgón / minibús hasta 19 pasajeros','$158.500']],columns=['Categoría publicada','CLP · por tramo'],note='Tarifario consultado el 22-10-2026. Categorías y recargos completos en el PDF oficial.',links=['porvenir-precios']),
 s('Cómo calcular un viaje con acompañantes','Para un automóvil de la categoría indicada, conductor y dos acompañantes adultos con tarifa general, la suma de referencia de un tramo es $78.500 + $12.000 + $12.000 = $102.500. Es un ejemplo aritmético del tarifario consultado, no una reserva ni una garantía de cupo.',
   'Para ida y vuelta calcula ambos pasajes y confirma que la salida de regreso existe en tu fecha. Añade alimentación, transporte del terminal y actividades si corresponden. Comparar esta cifra con Primera Angostura requiere incorporar además kilómetros, combustible y tiempo de carretera.'),
 s('Reservar y preparar el embarque','Compra en el sitio de TABSA o en sus oficinas, revisando pasajeros, sentido, fecha y vehículo. El medio de pago es el que habilite el proceso de compra o confirme la oficina: no se promete aquí que cualquier tarjeta extranjera, moneda o pago a bordo sea aceptado.',
   'Conserva la confirmación y sigue la presentación que figure en el billete. Si vas caminando, lleva tu equipaje de forma manejable; si embarcas un auto, ten a mano documentos y matrícula. Para asistencia de acceso o un requisito especial, consulta antes de comprar para que el operador pueda responder sobre esa nave y salida.'),
 s('Qué puedes hacer al llegar','Porvenir permite organizar un paseo urbano y patrimonial sin convertir todo el día en carretera. Para una visita con horario o un recinto cultural, revisa su atención y cómo llegar desde Bahía Chilota. El desembarque no coincide necesariamente con la puerta de la actividad.',
   'Para seguir hacia Bahía Inútil o la Reserva Pingüino Rey necesitas transporte terrestre y cupo de visita. No se presenta el ferry como un tour que incluya esas actividades. Si haces el circuito con una agencia, pregunta qué cruce utilizará en cada sentido y cómo se resuelven cambios por clima.'),
 s('Vuelta, viento y contacto','No esperes al final de la visita para comprobar el regreso. Consulta el estado operativo y deja margen para volver al terminal. Si el itinerario se modifica, gestiona alternativas con TABSA y con cualquier actividad que tengas contratada; un horario anterior en una captura no acredita una salida confirmada.',
   'El contacto publicado por TABSA es +56 61 272 8100 y reservas@tabsa.cl. No los presento como WhatsApp: el sitio los identifica como teléfono y correo. Guarda el punto de embarque y el horario de tu billete antes de salir de Punta Arenas.',links=['tabsa-terminales','tabsa-estado'])],
 'Yo reservaría primero el regreso y después decidiría cuánto recorrer en la isla. Así sabes cuánto tiempo real tienes para disfrutar Porvenir.',
 ['porvenir','porvenir-horas','porvenir-precios','tabsa-faq','tabsa-terminales'],[('Tres Puentes · embarque en Punta Arenas','Embarcadero Tres Puentes Juan Williams 06450 Punta Arenas'),('Bahía Chilota · desembarque en Tierra del Fuego','Terminal TABSA Bahia Chilota Porvenir')],inline=[(3,'mapa-porvenir')]),

page('primera-angostura','Primera Angostura: cruce, horarios y valores',
 'Punta Delgada y Bahía Azul conectan el continente con Tierra del Fuego. Es un cruce corto, pero desde Punta Arenas debes organizar antes la carretera y después la continuación en la isla.',
 'Estrecho y Tierra del Fuego','primera-angostura',[
 s('La ubicación que define la jornada','TABSA sitúa Primera Angostura a unos 160 kilómetros de Punta Arenas y describe una separación de aproximadamente cinco kilómetros entre Punta Delgada y Bahía Azul. No sales desde el puerto urbano: primero debes llegar por tierra al terminal del continente.',
   'La navegación es solo una parte del circuito. Para Porvenir, Cerro Sombrero o Bahía Inútil, calcula el tramo de carretera después de desembarcar y el regreso. No uses la duración de una travesía corta como si fuera el tiempo desde tu hotel hasta el destino final.'),
 s('Horario publicado y última salida de cada lado','El aviso del operador, válido desde el 1 de marzo de 2026, indica operación de lunes a domingo entre 08:30 y 23:00, incluidos festivos. Lo decisivo es que el último zarpe del continente y el de la isla no son a la misma hora.',
   rows=[['Punta Delgada → Bahía Azul','Último zarpe publicado: 22:00'],['Bahía Azul → Punta Delgada','Último zarpe publicado: 23:00'],['Inicio de ventana de operación','08:30']],columns=['Sentido / referencia','Horario publicado'],note='Consultar el estado del cruce. Clima, fuerza mayor y contingencias pueden modificar la operación; no llegar sobre la hora límite.',links=['angostura-horas','tabsa-estado']),
 s('Tarifas de Primera Angostura','El tarifario publicado indica vigencia desde el 9 de abril de 2026. Los pasajeros figuran gratis. Los rodados se cobran según categoría y dimensiones; un motorhome o una van no se deben presupuestar como automóvil sin confirmar su clasificación.',
   rows=[['Pasajeros','Gratis'],['Automóvil o camioneta hasta 6 metros','$26.000'],['Moto o cuatrimoto','$13.000'],['Motorhome, van, minibús o furgón hasta 19 pasajeros','$52.000'],['Carro de arrastre hasta 6 metros, incluida lanza','$26.000']],columns=['Categoría publicada','CLP · por cruce'],note='Consultar categorías, medidas y recargos en el documento completo antes de viajar.',links=['angostura-precios']),
 s('Compra, fila y paso del vehículo','Los pasajes se pueden adquirir en los canales de TABSA. Su información general indica una validez de 90 días para los pasajes comprados online de Primera Angostura. Eso no debe interpretarse como una hora de embarque o un lugar garantizado en cualquier fila: revisa las condiciones del servicio que compras.',
   'Sigue las indicaciones del personal para ingresar, detenerte y desembarcar. Antes de conducir a la rampa deja resueltos el comprobante y la categoría del vehículo. Si necesitas un medio de pago específico, confírmalo antes de salir; una fila operativa no garantiza que todos los métodos estén habilitados allí.'),
 s('Qué puede sumar el sector al viaje','En los terminales hay oficinas de TABSA. El operador menciona servicios de restaurante y supermercado en Punta Delgada, además del reloj solar ecuatorial y el faro como referencias del sector. No se publica un horario comercial ni acceso interior a esos lugares sin verificación.',
   'Puedes aprovechar una pausa de acuerdo con el tiempo disponible, pero no te alejes de la coordinación del embarque para realizar una visita. Si el objetivo principal está más adentro de Tierra del Fuego, prioriza llegar a esa reserva o alojamiento con margen antes de sumar paradas.'),
 s('Viento, combustible y carretera','Consulta estado del cruce antes de iniciar los kilómetros de carretera. TABSA también informa a través de sus redes y de FM Angostura 104.5 en el área de cobertura local. Ten descargadas las ubicaciones de ambos terminales para no depender solo de una búsqueda con datos móviles.',
   'Revisa combustible, autonomía y el estado del camino de tu recorrido completo. Con vehículo arrendado, confirma permiso para embarcar y caminos admitidos. Para un cruce posterior a Argentina, prepara además la documentación fronteriza y del auto: el ticket del ferry no reemplaza esos trámites.'),
 s('Cómo comparar con el ferry a Porvenir','Para un automóvil de la categoría publicada, dos cruces de Primera Angostura sumarían $52.000 al mismo tarifario. La comparación con la ruta larga debe añadir combustible, kilómetros y tiempo. Si no llevas auto, la gratuidad del pasajero no resuelve cómo llegar hasta el terminal ni cómo continuar.',
   'Mi decisión dependería del destino final, de la hora de vuelta y de cuánta carretera quiero conducir. Si una actividad tiene cupo fijo, coordinaría su horario antes de salir. Evitaría enlazar el último cruce del día con un vuelo o bus posterior sin margen suficiente.')],
 'Yo anotaría las dos últimas salidas por separado: Punta Delgada a las 22:00 y Bahía Azul a las 23:00 según el aviso consultado. Después dejaría margen para llegar antes, no justo a esa hora.',
 ['angostura','angostura-horas','angostura-precios','tabsa-faq','tabsa-estado'],[('Punta Delgada · continente','Terminal TABSA Punta Delgada Primera Angostura'),('Bahía Azul · Tierra del Fuego','Terminal TABSA Bahia Azul Primera Angostura')]),

page('aeropuerto','Aeropuerto PUQ: centro, transfers y conexión a Natales',
 'La llegada se disfruta más con el primer traslado claro. Compara taxi oficial, servicio reservado, aplicaciones y la conexión interurbana según el destino real de tu viaje.',
 'Aeropuerto y rutas regionales','aeropuerto',[
 s('Primero identifica tu destino','El aeropuerto Presidente Carlos Ibáñez del Campo, PUQ, está en la Ruta 9 Norte, kilómetro 20,5. Si tu alojamiento está en Punta Arenas, busca una conexión al centro o a su sector. Si continúas hacia Puerto Natales, puede convenirte un servicio interurbano con embarque autorizado en el aeropuerto.',
   'Anota la dirección completa y cuántas personas y maletas llevan. Eso permite comparar servicios por vehículo o por asiento sin confundir el precio. No se presenta una micro urbana como conexión aeroportuaria sin un recorrido de ese servicio corroborado.'),
 s('Taxi oficial: cuánto publica el aeropuerto','El sitio actual de Aeropuertos Australes publica $13.000 para aeropuerto–ciudad o viceversa, $16.000 para Río de los Ciervos, Archipiélago Chiloé y 18 de Septiembre, y $18.000 para Leñadura y sectores aledaños al sur. Confirma que el total corresponde a tu dirección y vehículo.',
   'Solicita el servicio identificado y pregunta el medio de pago antes de salir. Una tarifa oficial por traslado no es un pasaje por persona ni una cotización para una excursión fuera de esos sectores. Para movilidad reducida o gran cantidad de equipaje, confirma el vehículo requerido.',links=['puq']),
 s('Transfer compartido o privado','Un servicio compartido puede transportar a varias personas con distintos destinos; uno privado se coordina para tu grupo. Pide un presupuesto que indique pasajeros, maletas, dirección, hora y espera por retraso de vuelo. No se publican valores de transfer que no hayan quedado comprobados.',
   'Si reservas antes de viajar, guarda cómo identificar al conductor y qué hacer si el vuelo cambia. Comprueba si te dejan en el alojamiento o en un punto de distribución. Para llegadas nocturnas, coordina también la recepción del hospedaje: resolver el transporte no garantiza que puedas entrar al edificio.'),
 s('Uber y otras aplicaciones en el aeropuerto','Introduce el destino y revisa los vehículos y precios disponibles. Sigue el punto de encuentro que indique la plataforma y las normas del terminal; no supongas que el conductor puede detenerse en cualquier acceso. Solicita cuando hayas recogido el equipaje y puedas dirigirte al lugar acordado.',
   'La disponibilidad puede cambiar, especialmente fuera de horas de mayor movimiento. Si no aparece un auto o se cancela una solicitud, compara con el servicio oficial o uno previamente coordinado. En la ficha de aplicaciones explico pagos, verificación del vehículo y cómo revisar la solicitud.'),
 s('La conexión Bus-Sur tiene un sentido específico','Bus-Sur documenta el aeropuerto como parada de subida en el sentido Punta Arenas → Puerto Natales y de bajada en Puerto Natales → Punta Arenas. Esa configuración no equivale a vender una lanzadera desde el aeropuerto al centro urbano. Revisa el origen y el destino al comprar.',
   'Para seguir directamente a Natales, consulta el pasaje desde el aeropuerto, la parada y la anticipación exigida. Deja margen entre llegada del vuelo y bus por desembarque y equipaje. Si el vuelo se retrasa, confirma cómo funciona un cambio de pasaje; las conexiones independientes no deben darse por protegidas.',links=['bus-sur-paradas','bus-sur']),
 s('Asistencia, vehículos arrendados y salida del terminal','Aeropuertos Australes publica asistencia a pasajeros con movilidad reducida, con solicitud anticipada y contacto informaciones.puq@reddeaeropuertos.cl y +56 9 9858 2521. Coordina la necesidad concreta con la aerolínea y el aeropuerto: una asistencia en terminal no confirma un auto accesible para el traslado urbano.',
   'Si retiras un auto, revisa oficina, horario de entrega, documentación y depósito antes de volar. La hora de aterrizaje y la hora de entrega del vehículo son distintas; un mostrador puede tener condiciones propias para servicios fuera de horario. Fotografía el estado del auto al recibirlo y conserva el contrato.'),
 s('Preparar el regreso al aeropuerto','Revisa la anticipación de tu aerolínea y suma el traslado más un margen por espera y clima. Para salida de madrugada, confirma el servicio antes. Si conduces un auto arrendado, añade combustible, devolución, revisión y traslado desde la oficina al terminal si hace falta.',
   'Mira el vuelo en el sitio de la compañía o del aeropuerto; no conviertas el estado de una pantalla en una garantía frente a cambios posteriores. Lleva documentos y equipaje listos, y conserva el contacto del traslado donde puedas consultarlo sin depender de una nueva búsqueda.')],
 'Yo elegiría el traslado según dónde dormiré esa noche. Si el destino es Puerto Natales, comprobaría primero la conexión desde PUQ; si es Punta Arenas, compararía el total hasta mi dirección.',
 ['puq','puq-vuelos','uber','bus-sur-paradas','bus-sur'],[('Aeropuerto PUQ','Aeropuerto Presidente Carlos Ibáñez del Campo Punta Arenas')]),

page('buses-interurbanos','Buses a Puerto Natales, Torres del Paine y Argentina',
 'Desde Punta Arenas puedes continuar por carretera a otros destinos patagónicos. Aquí importan tanto la empresa y el terminal como la fecha, el sentido y el margen entre conexiones.',
 'Aeropuerto y rutas regionales','terminal',[
 s('Punta Arenas–Puerto Natales','Bus-Sur publica servicio diario, una duración aproximada de 3 horas 15 minutos y tarifa desde $11.000 por tramo. Su terminal de Punta Arenas está en avenida Colón 842. Buses Fernández también conecta ambas ciudades y publica salida desde Armando Sanhueza 745.',
   'En Puerto Natales, ambas referencias sitúan el terminal rodoviario en avenida España 1455. Comprueba cuál figura en tu pasaje: no uses “terminal de Punta Arenas” como si todas las empresas salieran de la misma dirección. La tarifa “desde” no garantiza precio ni asiento para una fecha concreta.'),
 s('Horarios publicados para planificar','La programación de Bus-Sur para temporada alta, septiembre a abril, incluye las siguientes salidas desde Punta Arenas; algunos servicios empiezan más adelante. Buses Fernández indica salidas diarias dentro del bloque 07:00–20:00, pero cada horario se debe seleccionar en su sistema de compra.',
   rows=[['07:00, 10:00, 12:30, 14:00, 15:00, 17:00, 18:00, 19:00','Programación de temporada alta publicada.'],['21:00','Publicado desde octubre.'],['11:00','Publicado desde noviembre.'],['08:30','Publicado desde el 15 de noviembre.']],columns=['Bus-Sur · salida desde Punta Arenas','Condición publicada'],note='Consulta 22-10-2026. Elegir fecha en la venta oficial; verificar por separado el sentido de regreso.',links=['bus-sur','fernandez']),
 s('Compra, pago, embarque y equipaje','Compra en la web oficial o canal autorizado de la empresa y revisa nombre, documento, fecha, sentido, terminal y asiento. El medio de pago y las condiciones de cambio son los que indique esa compra. Guarda la confirmación y consulta qué debes mostrar al subir.',
   'Buses Fernández recomienda llegar quince minutos antes; si tu billete exige más anticipación, sigue esa indicación. Revisa el equipaje permitido, cargos por exceso y condiciones para mascotas o bicicletas con la empresa concreta. No traslades la política de una compañía a otra.'),
 s('Aeropuerto: subida o bajada según el sentido','Bus-Sur autoriza la subida en PUQ para continuar a Puerto Natales y la bajada en PUQ cuando viajas de Natales a Punta Arenas. Al comprar, selecciona la parada correcta y consulta dónde esperar. Un pasaje desde el terminal urbano no acredita automáticamente una recogida en otro lugar.',
   'Para tomar un vuelo después de llegar en bus, deja margen amplio por carretera y equipaje. Para tomar el bus después de aterrizar, calcula desembarque y retiro de maletas. Una duración estimada no garantiza una conexión independiente con un intervalo mínimo.'),
 s('Torres del Paine: organiza la conexión en Natales','Los servicios de acceso al parque que documenta Bus-Sur salen desde Puerto Natales y se organizan por paraderos. Identifica qué entrada o sector necesitas, como Laguna Amarga, Pudeto o Grey, y revisa el horario específico. El nombre Torres del Paine no describe un único punto de bajada.',
   'Consulta también el traslado final desde ese paradero hacia tu alojamiento o sendero y compra la entrada al parque por su canal vigente. Un bus interurbano no incluye automáticamente guía, catamarán ni alimentación. Para una visita de un día desde Punta Arenas, compara la logística completa con un tour organizado.',links=['bus-sur-conexiones']),
 s('Argentina: destino directo o combinación','Bus-Sur publica conexiones internacionales, entre ellas la combinación a El Calafate vía Puerto Natales. Algunas opciones enlazan el mismo día y otras requieren dormir antes de continuar. Comprueba ambos billetes, el tiempo entre servicios y el lugar de cambio; no supongas un bus directo por el nombre del destino final.',
   'Para Río Gallegos, Río Grande o Ushuaia, consulta qué salida existe realmente en la fecha elegida y si hay transbordos o cruce marítimo. No se publica una frecuencia diaria universal. Los controles fronterizos y la navegación pueden modificar la duración del viaje.'),
 s('Documentos, equipaje y actividades al llegar','Para cruzar de país, consulta requisitos de entrada, documentos de menores y restricciones de alimentos en las autoridades correspondientes. Las condiciones dependen del pasajero y del viaje; la compra del pasaje no reemplaza la autorización migratoria.',
   'En Puerto Natales puedes dedicar tiempo a la ciudad antes de seguir hacia el parque, en lugar de encadenar traslados sin pausa. Si tienes una excursión reservada, informa de tu hora estimada de llegada y conserva margen. También organiza dónde guardarás o retirarás las maletas durante la conexión.')],
 'Yo guardaría el terminal escrito junto al pasaje. Colón 842 y Armando Sanhueza 745 son referencias distintas; llegar al edificio correcto es parte del viaje.',
 ['bus-sur','bus-sur-paradas','bus-sur-conexiones','fernandez','fernandez-terminal'],[('Terminal Bus-Sur · Punta Arenas','Bus Sur Avenida Colon 842 Punta Arenas'),('Terminal Buses Fernández · Punta Arenas','Buses Fernandez Armando Sanhueza 745 Punta Arenas'),('Rodoviario Puerto Natales','Terminal Rodoviario Avenida España 1455 Puerto Natales')]),

page('arriendo-autos','Arrendar auto: libertad y condiciones que conviene revisar',
 'Un auto ayuda a recorrer sectores alejados y armar tu propio ritmo. La decisión no depende solo de la tarifa diaria: también de caminos, seguro, combustible, ferry y devolución.',
 'Por tu cuenta','pali-aike',[
 s('Cuándo elegir un auto','Puede ser útil para varias visitas fuera de la ciudad, un grupo que comparta gastos o un circuito por Tierra del Fuego. Para un día concentrado en el centro, quizá no necesites conducir: compara traslados puntuales y caminatas antes de pagar varios días de arriendo.',
   'No hay una tarifa diaria fija que sirva para todas las temporadas o compañías. Cotiza fechas exactas, categoría y lugar de entrega. Compara el costo completo con la comodidad de un tour si visitarás una reserva o un sendero al que no quieras conducir.'),
 s('Qué preguntar al reservar','Pide por escrito los documentos aceptados, edad mínima, conductor adicional y tipo de tarjeta requerida para la garantía. Comprueba el depósito y el plazo de liberación, no solo el valor del arriendo. Una tarjeta que sirve para pagar no necesariamente cumple las condiciones de garantía de la arrendadora.',
   'Aclara seguro, deducible, exclusiones y asistencia en ruta. Si necesitas silla infantil o espacio de maletero, confírmalo en la reserva. “Similar” describe una categoría: no asegura una marca ni una configuración exacta de equipamiento.'),
 s('Carreteras, ripio y lugares para visitar','Para Fuerte Bulnes o Parque del Estrecho, revisa el acceso y horario de visita antes de organizar la conducción. Para Pali Aike, Laguna Parrillar o el inicio de una caminata, pregunta a la compañía si permite ese camino y qué cobertura mantiene allí.',
   'Un vehículo alto o con aspecto de todoterreno no autoriza por sí solo cualquier pista. Planifica la autonomía, descarga mapas y comprueba condiciones meteorológicas. En la jornada, ajusta el recorrido a la luz disponible y evita sumar destinos cuya distancia no habías calculado.'),
 s('Ferry y cruce a Argentina','Para embarcar el auto, consulta la autorización contractual y la categoría que corresponde en TABSA. Una van o motorhome tiene una tarifa distinta del automóvil. Si aún no sabes la matrícula al reservar el cruce, sigue el procedimiento que te confirme el operador antes del embarque.',
   'Para Argentina debes coordinar con anticipación la autorización de la arrendadora, el seguro y la documentación de salida y entrada exigida para ese vehículo y pasajeros. No se asegura aquí que todas las compañías permitan el cruce ni que puedan emitir permisos en el momento del retiro.'),
 s('Retiro, combustible y devolución','Al recibir el auto, revisa daños, neumáticos, herramientas, combustible y documentación; guarda fotografías y el inventario firmado. Aprende los mandos que necesites antes de incorporarte a la carretera. Consulta un número de asistencia que funcione para tu ruta.',
   'Para devolverlo, verifica dirección, hora, combustible y procedimiento fuera del horario de oficina. Si lo entregas antes de un vuelo, deja margen para revisión y traslado al terminal. No se promete una devolución automática en una ciudad distinta sin confirmación de esa reserva.'),
 s('Un presupuesto más completo','Suma arriendo, garantía disponible, cobertura elegida, combustible, estacionamiento, ferry y eventuales permisos. La garantía no es necesariamente un gasto definitivo, pero requiere fondos o cupo. Haz la comparación para todo el grupo y para el número real de jornadas.',
   'Conducir te da flexibilidad para detenerte y fotografiar, pero también deja en tus manos el regreso y las distancias. Yo armaría una ruta por sector, con una actividad principal y tiempo para disfrutarla. El auto sirve mejor cuando acompaña el viaje que quieres hacer, no cuando obliga a pasar todo el día al volante.')],
 'Yo pediría dos confirmaciones antes de pagar: que el auto puede ir por mis caminos y que puede embarcar o cruzar frontera si mi itinerario lo necesita.',
 ['puq-vuelos','porvenir-precios','angostura-precios','tabsa-faq'],[('Aeropuerto: referencia para el retiro reservado','Aeropuerto Presidente Carlos Ibáñez del Campo Punta Arenas')]),

page('a-pie-bicicleta','A pie y en bicicleta: mirar la ciudad a otro ritmo',
 'Para el centro y la Costanera, caminar puede formar parte de la visita. Una bicicleta amplía el paseo si el viento, el acceso y tus condiciones acompañan.',
 'Por tu cuenta','costanera',[
 s('Un centro que se puede recorrer por sectores','Puedes organizar un paseo alrededor de la plaza Muñoz Gamero, sus fachadas y las calles cercanas, y continuar hacia la Costanera según el clima. No necesitas convertir todas las visitas urbanas en traslados motorizados. Decide cuánto quieres caminar y deja un punto cómodo para volver.',
   'Para incluir un museo o un edificio por dentro, revisa su horario y reserva cuando corresponda. El mapa sirve para medir el trayecto entre direcciones, pero no acredita accesibilidad de toda la vereda. Si llevas maletas, organiza su custodia antes de salir a caminar.'),
 s('Cómo combinar paseo y transporte','Una micro o colectivo que coincida con tu alojamiento puede dejarte en un sector desde el que sigas a pie. Para un mirador, el esfuerzo cambia con la pendiente: comprueba cómo subir y cómo volver. Con lluvia o viento, puedes acortar el tramo exterior y sumar una pausa bajo techo.',
   'No es necesario recorrer todo en línea recta. Un circuito breve con una actividad interior y una comida suele ser más cómodo que varias caminatas largas sin descanso. Mira el regreso antes de empezar si dependes del último bus o de un acceso que cierre.'),
 s('Bicicleta: confirmar primero el servicio','No se ha verificado una red pública de bicicletas compartidas con estaciones y tarifa vigente para toda Punta Arenas. Si quieres arrendar, consulta a un proveedor concreto por disponibilidad, precio, garantía, casco, candado y asistencia. No se inventa aquí una aplicación o sistema municipal.',
   'Comprueba dónde puedes circular y estacionar, y el estado de la bicicleta antes de recibirla. Si piensas combinarla con bus o ferry, consulta previamente cómo se admite y cobra en ese servicio. Arrendar una bicicleta no incluye automáticamente su transporte en otro medio.'),
 s('Viento, abrigo y tiempos reales','Elige el recorrido según las condiciones del día. El viento de frente, la lluvia o el frío pueden cambiar cuánto disfrutas una distancia que parece corta en la pantalla. Lleva abrigo manejable, guarda objetos que puedan volarse y programa paradas que puedas ajustar.',
   'Para pedalear fuera del centro necesitas una planificación distinta de un paseo urbano: ruta admitida, tránsito, autonomía y regreso. No se recomienda aquí una carretera como ciclovía sin validación. Si no conoces el sector, empieza por un trayecto corto y conserva una alternativa de vuelta.'),
 s('Mapa y accesibilidad','El mapa al final identifica referencias urbanas, no una ruta accesible certificada ni una ciclovía señalizada. Antes de comprometer una jornada con movilidad reducida, pregunta por acceso al recinto y estado del recorrido final desde la calle.',
   'Guarda un mapa sin conexión para orientarte, pero utiliza la información local y la señalización al llegar. Si cambia el clima, puedes terminar el paseo y usar un taxi o una app para volver. La ventaja de caminar por sectores es poder decidir cuánto seguir sin perder todo el plan.')],
 'Yo dejaría que el viento elija el tamaño del paseo. Una caminata breve por el centro, con tiempo para entrar a un museo o sentarse a comer, también es conocer Punta Arenas.',
 ['red-ios','red-android'],[('Plaza Muñoz Gamero','Plaza Muñoz Gamero Punta Arenas'),('Costanera: referencia urbana','Costanera del Estrecho Punta Arenas')]),

page('conexiones-australes','Vuelos regionales y otras conexiones australes',
 'Porvenir y Puerto Williams también tienen conexiones aéreas desde Punta Arenas. Para llegar más al sur o enlazar fiordos, compara el calendario completo y la forma de continuar desde cada terminal.',
 'Aeropuerto y rutas regionales','dap-regional',[
 s('Vuelos regulares con DAP','DAP publica rutas regulares desde Punta Arenas a Porvenir y Puerto Williams. Su calendario permite comparar el vuelo con la navegación, especialmente si tu prioridad es dedicar más tiempo al destino. El precio depende de fecha, disponibilidad y condiciones; no se publica una tarifa aérea fija sin una cotización vigente.',
   'El aeropuerto de Porvenir y Bahía Chilota son puntos de llegada diferentes. En Puerto Williams, revisa el acceso desde el aeródromo hasta tu alojamiento. La reserva del vuelo no incluye automáticamente esos traslados, una excursión ni transporte para el equipaje fuera de la franquicia contratada.'),
 s('Frecuencias publicadas al revisar la guía','El sitio de DAP distingue octubre y el periodo noviembre–marzo para Puerto Williams, y publica Porvenir de lunes a viernes. Estos datos ayudan a armar el itinerario; la reserva y el vuelo seleccionado son la referencia final para viajar.',
   rows=[['PUQ → Porvenir','Lunes a viernes','08:15 y 16:30'],['Porvenir → PUQ','Lunes a viernes','08:35 y 17:00'],['PUQ → Puerto Williams','Octubre: lunes, martes, miércoles, viernes y sábado','08:00'],['Puerto Williams → PUQ','Mismos días de octubre','09:45'],['Puerto Williams · noviembre a marzo','Lunes a sábado','PUQ 08:00 / regreso 09:45']],columns=['Ruta','Frecuencia publicada','Horario'],note='Consulta 22-10-2026. Confirmar fecha, disponibilidad, terminal y presentación con DAP.',links=['dap']),
 s('Equipaje, cambios y necesidades de asistencia','Compara la franquicia incluida, dimensiones de cabina, equipaje facturado y recargos antes de comprar. Las condiciones pueden ser diferentes de un vuelo de mayor tamaño o una tarifa de otra aerolínea. Si transportas equipo deportivo o necesitas asistencia, solicita confirmación para la ruta concreta.',
   'Guarda las condiciones de cambio y reprogramación. Si enlazas con otro vuelo comprado por separado, deja margen por clima, equipaje y nueva presentación. La programación regular no garantiza que una conexión independiente con pocos minutos entre vuelos sea adecuada.'),
 s('Por mar hacia Puerto Williams','TABSA ofrece una conexión entre Punta Arenas y Puerto Williams por canales australes. Es un viaje distinto del cruce corto a Tierra del Fuego: el calendario, la duración y la acomodación deben consultarse en la ruta específica. No se traslada el precio del Pathagon a este servicio.',
   'Comprueba el tipo de asiento o acomodación, alimentación, equipaje, posibilidad de embarcar vehículo y políticas ante cambios. Para un viaje con caminatas en Navarino, reserva también alojamiento y transporte local. El terminal marítimo y el aeródromo no son intercambiables al coordinar la llegada.',links=['tabsa']),
 s('Fiordos y Carretera Austral: también hay que llegar al puerto','Las conexiones marítimas desde Puerto Natales hacia localidades de los fiordos requieren primero organizar el traslado a Natales y el embarque indicado por el operador. No se presentan como salidas desde Punta Arenas por compartir la misma región o empresa.',
   'Para continuar hacia Caleta Tortel, Puerto Yungay u otra localidad, consulta cada tramo y qué combinación está operativa para tu fecha. Mira dónde dormir, cómo llevar el vehículo si corresponde y qué pasa si una navegación se retrasa. Una línea en el mapa no sustituye un calendario de conexiones disponible.'),
 s('Elegir por el viaje que quieres vivir','El avión puede reducir el tiempo de desplazamiento; la navegación puede ser parte de la experiencia. Compara precio total, equipaje, acceso al terminal y cuántos días tienes. Para Porvenir, un vuelo de ida y un ferry de vuelta pueden ser una posibilidad solo si ambos pasajes y los traslados encajan.',
   'Yo dejaría jornadas flexibles para destinos australes y confirmaría directamente con los operadores cualquier enlace delicado. No necesitas elegir siempre lo más rápido: necesitas una combinación que puedas realizar con margen y que te permita disfrutar el lugar al que vas.')],
 'Yo compararía el tiempo desde la puerta del alojamiento hasta el destino, no solo los minutos de vuelo o navegación. Los traslados y la espera también forman parte del viaje.',
 ['dap','puq-vuelos','tabsa','bus-sur-conexiones'],[('Salida aérea: aeropuerto PUQ','Aeropuerto Presidente Carlos Ibáñez del Campo Punta Arenas'),('Salida marítima: Tres Puentes','Embarcadero Tres Puentes Punta Arenas')]),
]
